#include <iostream>
#include <fstream>
#include <iterator>
#include <optional>
#include "parser.h"
#include "parse_glob.h"
#include <oniguruma.h>

static bool matches(const std::string& glob, const std::string& path) {
    const auto pattern=convert_glob_to_regexp(glob,false);
    const auto* p=reinterpret_cast<const OnigUChar*>(pattern.data());
    const auto* q=reinterpret_cast<const OnigUChar*>(path.data());
    regex_t* compiled=nullptr;
    OnigErrorInfo error;
    const auto rc=onig_new(&compiled,p,p+pattern.size(),ONIG_OPTION_NONE,ONIG_ENCODING_UTF8,ONIG_SYNTAX_RUBY,&error);
    if(rc!=ONIG_NORMAL) throw std::runtime_error("invalid settings glob");
    auto* region=onig_region_new();
    const auto outcome=onig_search(compiled,q,q+path.size(),q,q+path.size(),region,ONIG_OPTION_NONE);
    onig_region_free(region,1);
    onig_free(compiled);
    return outcome>=0;
}
static std::optional<std::string> property(const ini_file_t& properties,const std::string& path) {
    std::optional<std::string> value;
    for(const auto& section:properties.sections) {
        const bool enabled=std::any_of(section.names.begin(),section.names.end(),
            [&path](const auto& glob){return matches(glob,path);});
        if(enabled)for(const auto& setting:section.values)if(setting.name=="GREETING")value=setting.value;
    }
    return value;
}
int main() {
    std::ifstream stream(".tm_properties",std::ios::binary);
    const std::string input{std::istreambuf_iterator<char>(stream),{}};
    ini_file_t properties(".tm_properties");
    if(!stream.is_open() || parse_ini(input.data(),input.data()+input.size(),properties)!=input.data()+input.size())return 2;
    OnigEncoding encodings[]={ONIG_ENCODING_UTF8};
    if(onig_initialize(encodings,1)!=ONIG_NORMAL)return 3;
    const auto text=property(properties,"greeting.txt");
    const auto markdown=property(properties,"greeting.md");
    onig_end();
    if(!text || markdown)return 4;
    std::cout << *text << '\n';
}
